contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 newFundingFee, address account) public {
        bool reverted;
        try c.updateFundingFee(newFundingFee) { reverted = false; }
        catch { reverted = true; }

        // Rule: for ANY fee value, an uninitialized Product cannot have its
        // funding fee updated: the notPaused / onlyProductOwner checks must
        // force a revert since no controller was ever initialized.
        assert(reverted);

        // account is exercised too: even a follow-up account-scoped settle
        // must revert on the uninitialized product for any address.
        bool reverted2;
        try c.settleAccount(account) { reverted2 = false; }
        catch { reverted2 = true; }
        assert(reverted2);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address account, uint256 amount) public payable {
        // state-independent preconditions on inputs only
        require(amount <= type(uint256).max / 2);

        // before any mutating call: a fresh product has no positions and no versions
        Position memory posBefore = c.position(account);
        uint256 acctVersion = c.latestVersion(account);
        uint256 globalVersion = c.latestVersion();
        PrePosition memory preBefore = c.pre();
        PrePosition memory acctPre = c.pre(account);

        bool revertedOpenMake;
        try c.openMakeFor(account, UFixed18.wrap(amount)) { revertedOpenMake = false; }
        catch { revertedOpenMake = true; }

        bool revertedOpenTake;
        try c.openTakeFor(account, UFixed18.wrap(amount)) { revertedOpenTake = false; }
        catch { revertedOpenTake = true; }

        bool revertedCloseMake;
        try c.closeMakeFor(account, UFixed18.wrap(amount)) { revertedCloseMake = false; }
        catch { revertedCloseMake = true; }

        bool revertedCloseTake;
        try c.closeTakeFor(account, UFixed18.wrap(amount)) { revertedCloseTake = false; }
        catch { revertedCloseTake = true; }

        // after all failed attempts, state is still empty
        Position memory posAfter = c.position(account);
        uint256 acctVersionAfter = c.latestVersion(account);
        uint256 globalVersionAfter = c.latestVersion();

        assert(
            revertedOpenMake && revertedOpenTake && revertedCloseMake && revertedCloseTake &&
            UFixed18.unwrap(posBefore.maker) == 0 && UFixed18.unwrap(posBefore.taker) == 0 &&
            UFixed18.unwrap(posAfter.maker) == 0 && UFixed18.unwrap(posAfter.taker) == 0 &&
            acctVersion == 0 && acctVersionAfter == 0 &&
            globalVersion == 0 && globalVersionAfter == 0 &&
            preBefore.oracleVersion == 0 && acctPre.oracleVersion == 0
        );
    }

    receive() external payable {}
}

