contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address a) public {
        require(true);

        Position memory pos = c.position(a);
        PrePosition memory pre = c.pre(a);
        bool isClosed = c.closed();
        bool accountClosed = c.isClosed(a);
        bool liquidating = c.isLiquidating(a);
        uint256 version = c.latestVersion();
        UFixed18 maint = c.maintenance(a);
        UFixed18 maintNext = c.maintenanceNext(a);

        // A product that has never been initialized nor traded must report
        // entirely empty state for every address.
        assert(
            pos.maker.isZero() &&
            pos.taker.isZero() &&
            pre.oracleVersion == 0 &&
            pre.openPosition.maker.isZero() &&
            pre.openPosition.taker.isZero() &&
            pre.closePosition.maker.isZero() &&
            pre.closePosition.taker.isZero() &&
            !isClosed &&
            !accountClosed &&
            !liquidating &&
            maint.isZero() &&
            maintNext.isZero() &&
            version == 0
        );
    }

    receive() external payable {}
}

