contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address other, UFixed18 amount) public {
        require(other != address(this));
        require(UFixed18.unwrap(amount) > 0);

        // calling on behalf of a different account must revert (authorization check)
        bool reverted;
        try c.closeTakeFor(other, amount) { reverted = false; } catch { reverted = true; }

        // calling on own account must succeed and record the close position
        c.closeTakeFor(address(this), amount);
        PrePosition memory preAfter = c.pre(address(this));

        assert(
            reverted &&
            UFixed18.unwrap(preAfter.closePosition.taker) == UFixed18.unwrap(amount) &&
            UFixed18.unwrap(preAfter.closePosition.maker) == 0
        );
    }

    receive() external payable {}
}

