contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        int256 minRate,
        int256 maxRate,
        int256 targetRate,
        uint256 targetUtilization
    ) public {
        require(minRate <= type(int128).max && minRate >= type(int128).min);
        require(maxRate <= type(int128).max && maxRate >= type(int128).min);
        require(targetRate <= type(int128).max && targetRate >= type(int128).min);
        require(targetUtilization <= type(uint128).max);

        IProduct.ProductInfo memory info;
        info.name = "t";
        info.symbol = "t";
        info.oracle = IOracleProvider(address(c));
        info.maintenance = UFixed18.wrap(0);
        info.fundingFee = UFixed18.wrap(0);
        info.makerFee = UFixed18.wrap(0);
        info.takerFee = UFixed18.wrap(0);
        info.positionFee = UFixed18.wrap(0);
        info.makerLimit = UFixed18.wrap(0);
        info.utilizationCurve = JumpRateUtilizationCurve(
            PackedFixed18.wrap(int128(minRate)),
            PackedFixed18.wrap(int128(maxRate)),
            PackedFixed18.wrap(int128(targetRate)),
            PackedUFixed18.wrap(uint128(targetUtilization))
        );

        c.initialize(info);

        JumpRateUtilizationCurve memory curve = c.utilizationCurve();
        assert(
            PackedFixed18.unwrap(curve.minRate) == minRate &&
            PackedFixed18.unwrap(curve.maxRate) == maxRate &&
            PackedFixed18.unwrap(curve.targetRate) == targetRate &&
            PackedUFixed18.unwrap(curve.targetUtilization) == targetUtilization
        );
    }

    receive() external payable {}
}

