contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amountA, uint256 amountB) public {
        require(amountB <= type(uint256).max - amountA, "overflow of total");

        address self = address(this);
        uint256 before = UFixed18.unwrap(c.pre(self).openPosition.taker);
        require(before <= type(uint256).max - amountA, "overflow 1");

        c.openTake(UFixed18.wrap(amountA));
        uint256 mid = UFixed18.unwrap(c.pre(self).openPosition.taker);

        c.openTake(UFixed18.wrap(amountB));
        uint256 after_ = UFixed18.unwrap(c.pre(self).openPosition.taker);

        assert(mid == before + amountA && after_ == mid + amountB);
    }

    receive() external payable {}
}

