contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bool newClosed) public payable {
        // Precondition: product is fresh/uninitialized (checked below via oracle behavior,
        // not via state reads of c before the deciding call).

        // read-only observation: closed flag before
        bool closedBefore = c.closed();

        // deciding call #1: attempt to close/open the product
        bool updateReverted;
        try c.updateClosed(newClosed) { updateReverted = false; } catch { updateReverted = true; }

        // deciding call #2: attempt a direct settle (same oracle dependency)
        bool settleReverted;
        try c.settle() { settleReverted = false; } catch { settleReverted = true; }

        // read-only observation: closed flag after
        bool closedAfter = c.closed();

        assert(
            closedBefore == false &&
            updateReverted == true &&
            settleReverted == true &&
            closedAfter == false
        );
    }

    receive() external payable {}
}

